const input = $("When Executed by Another Workflow")
  .first().json;

const filters = input.search_filters ?? {};

const properties = $input.all().map(item => item.json);

const location = String(filters.location ?? "")
  .trim().toLowerCase();

const bedrooms = filters.bedrooms == null ||
  filters.bedrooms === ""
  ? null : Number(filters.bedrooms);

const maxPrice = filters.max_price_ngn == null ||
  filters.max_price_ngn === ""
  ? null : Number(filters.max_price_ngn);

const propertyType = String(filters.property_type ?? "")
  .trim().toLowerCase();

const matches = properties.filter(property => {
  if (property.publication_state !== "published" ||
      property.rental_availability !== "available" ||
      !["vetted", "verified"].includes(property.verification_state)) return false;

  if (location) {
    const searchableLocation = [
      property.location,
      property.neighborhood
    ].filter(Boolean).join(" ").toLowerCase();

    if (!searchableLocation.includes(location)) return false;
  }

  if (bedrooms !== null &&
      (!Number.isFinite(bedrooms) ||
       Number(property.bedrooms) !== bedrooms)) return false;

  if (maxPrice !== null &&
      (!Number.isFinite(maxPrice) ||
       Number(property.price_ngn) > maxPrice)) return false;

  if (propertyType &&
      String(property.property_type).toLowerCase() !==
      propertyType) return false;

  return true;
});

return [{
  json: {
    count: matches.length,
    matches: matches.map(property => Object.fromEntries(
      ["id","slug","reference","title","tagline","description","property_type","price_ngn","price_period","rent_annual","currency","state","city","location","neighborhood","address_short","bedrooms","bathrooms","toilets","power_rating","water_supply","security_rating","verification_state","publication_state","rental_availability","featured_image","features","nearby_landmarks","created_at","updated_at"].map(key => [key, property[key]])
    )),
    message: matches.length
      ? "Matching verified properties found."
      : "No matching verified properties found."
  }
}];
